ALTER TABLE gb_channel ADD COLUMN IF NOT EXISTS recording_mode VARCHAR(16) NOT NULL DEFAULT 'off';
UPDATE gb_channel SET recording_mode = CASE WHEN cloud_recording_enabled THEN 'continuous' ELSE 'off' END;
CREATE TABLE IF NOT EXISTS gb_recording_plan (id BIGSERIAL PRIMARY KEY, name VARCHAR(128) NOT NULL, description VARCHAR(500) NOT NULL DEFAULT '', status SMALLINT NOT NULL DEFAULT 1, version BIGINT NOT NULL DEFAULT 1, owner_dept_id BIGINT NOT NULL, created_by BIGINT NOT NULL DEFAULT 0, updated_by BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(3) NOT NULL, updated_at TIMESTAMP(3) NOT NULL, deleted_at TIMESTAMP(3));
CREATE INDEX IF NOT EXISTS idx_recording_plan_dept_deleted ON gb_recording_plan(owner_dept_id,deleted_at);
CREATE TABLE IF NOT EXISTS gb_recording_plan_period (id BIGSERIAL PRIMARY KEY, plan_id BIGINT NOT NULL, weekday SMALLINT NOT NULL, start_slot SMALLINT NOT NULL, end_slot SMALLINT NOT NULL, created_at TIMESTAMP(3) NOT NULL, updated_at TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_recording_plan_period_plan_weekday ON gb_recording_plan_period(plan_id,weekday);
CREATE TABLE IF NOT EXISTS gb_recording_plan_binding (id BIGSERIAL PRIMARY KEY, plan_id BIGINT NOT NULL, channel_id BIGINT NOT NULL, owner_dept_id BIGINT NOT NULL, assigned_by BIGINT NOT NULL DEFAULT 0, assigned_at TIMESTAMP(3) NOT NULL, created_at TIMESTAMP(3) NOT NULL, updated_at TIMESTAMP(3) NOT NULL, CONSTRAINT uk_recording_plan_binding_channel UNIQUE(channel_id));
CREATE INDEX IF NOT EXISTS idx_recording_plan_binding_plan ON gb_recording_plan_binding(plan_id);
CREATE TABLE IF NOT EXISTS gb_recording_plan_channel_state (channel_id BIGINT PRIMARY KEY, plan_id BIGINT, plan_version BIGINT NOT NULL DEFAULT 0, desired_state VARCHAR(24) NOT NULL, actual_state VARCHAR(32) NOT NULL, reason_code VARCHAR(64) NOT NULL DEFAULT '', reason_message VARCHAR(500) NOT NULL DEFAULT '', next_transition_at TIMESTAMP(3), next_retry_at TIMESTAMP(3), reconcile_at TIMESTAMP(3) NOT NULL, attempt_count INTEGER NOT NULL DEFAULT 0, generation BIGINT NOT NULL DEFAULT 0, stream_id VARCHAR(64) NOT NULL DEFAULT '', recording_session_id BIGINT, node_id VARCHAR(64) NOT NULL DEFAULT '', last_media_at TIMESTAMP(3), last_success_at TIMESTAMP(3), lease_owner VARCHAR(128) NOT NULL DEFAULT '', lease_until TIMESTAMP(3), state_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(3) NOT NULL, updated_at TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_recording_plan_state_reconcile ON gb_recording_plan_channel_state(reconcile_at,channel_id);
CREATE INDEX IF NOT EXISTS idx_recording_plan_state_retry ON gb_recording_plan_channel_state(next_retry_at,channel_id);
CREATE TABLE IF NOT EXISTS gb_recording_plan_execution (id BIGSERIAL PRIMARY KEY, plan_id BIGINT, channel_id BIGINT NOT NULL, device_id VARCHAR(20) NOT NULL DEFAULT '', action VARCHAR(32) NOT NULL, trigger_source VARCHAR(32) NOT NULL, stage VARCHAR(32) NOT NULL DEFAULT '', attempt INTEGER NOT NULL DEFAULT 1, result VARCHAR(24) NOT NULL, reason_code VARCHAR(64) NOT NULL DEFAULT '', reason_message VARCHAR(500) NOT NULL DEFAULT '', stream_id VARCHAR(64) NOT NULL DEFAULT '', node_id VARCHAR(64) NOT NULL DEFAULT '', recording_session_id BIGINT, generation BIGINT NOT NULL DEFAULT 0, started_at TIMESTAMP(3) NOT NULL, ended_at TIMESTAMP(3), duration_ms BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_recording_plan_execution_channel ON gb_recording_plan_execution(channel_id,started_at);
CREATE TABLE IF NOT EXISTS gb_recording_plan_gap (id BIGSERIAL PRIMARY KEY, plan_id BIGINT, channel_id BIGINT NOT NULL, started_at TIMESTAMP(3) NOT NULL, ended_at TIMESTAMP(3), duration_ms BIGINT NOT NULL DEFAULT 0, reason_code VARCHAR(64) NOT NULL, reason_message VARCHAR(500) NOT NULL DEFAULT '', recovered BOOLEAN NOT NULL DEFAULT FALSE, execution_id BIGINT, created_at TIMESTAMP(3) NOT NULL, updated_at TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_recording_plan_gap_channel ON gb_recording_plan_gap(channel_id,started_at);
